### 1. `src/app/watchlist-store.ts` — add `restore`

```ts
import { Injectable, computed, effect, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
  private readonly _items = signal<WatchItem[]>([]);
  readonly items = this._items.asReadonly();
  readonly count = computed(() => this._items().length);

  constructor() {
    effect(() => {
      try {
        localStorage.setItem('watchlist', JSON.stringify(this._items()));
      } catch {}
    });
  }

  add(movie: TmdbMovie): void {
    this._items.update(items =>
      items.some(m => m.id === movie.id)
        ? items
        : [...items, { id: movie.id, title: movie.title, poster_path: movie.poster_path, release_date: movie.release_date, watched: false }],
    );
  }

  restore(item: WatchItem, index: number): void {
    this._items.update(items => {
      if (items.some(m => m.id === item.id)) return items;
      const next = [...items];
      const at = Math.max(0, Math.min(index, next.length));
      next.splice(at, 0, item);
      return next;
    });
  }

  remove(id: number): void {
    this._items.update(items => items.filter(m => m.id !== id));
  }

  toggleWatched(id: number): void {
    this._items.update(items => items.map(m => (m.id === id ? { ...m, watched: !m.watched } : m)));
  }
}
```

