import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { WatchItem } from '../movie';
import { WatchlistStore } from '../watchlist-store';

export type WatchlistFilter = 'all' | 'unwatched' | 'watched';

@Component({
  selector: 'app-watchlist',
  imports: [RouterLink],
  templateUrl: './watchlist.html',
  styleUrl: './watchlist.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class Watchlist {
  protected readonly store = inject(WatchlistStore);
  protected readonly movies = computed(() => this.store.items());
  protected readonly filter = signal<WatchlistFilter>('all');

  protected readonly visibleMovies = computed(() => {
    switch (this.filter()) {
      case 'unwatched':
        return this.movies().filter(movie => !movie.watched);
      case 'watched':
        return this.movies().filter(movie => movie.watched);
      default:
        return this.movies();
    }
  });

  protected readonly unwatchedCount = computed(() => this.movies().length - this.watchedCount());

  protected readonly lastRemoved = signal<{ item: WatchItem; index: number } | null>(null);
  protected readonly announcement = computed(() => {
    const removed = this.lastRemoved();
    return removed ? `Removed ${removed.item.title} from your watchlist` : '';
  });

  protected readonly filterHint = computed(() =>
    this.filter() === 'watched'
      ? 'No watched movies yet. Tick a movie off once you have seen it.'
      : 'You have watched everything on your list. Time to find more movies!');

  protected readonly watchedCount = computed(() => this.movies().filter(m => m.watched).length);
  ...
}
```

